"""
Task 011 — Topological sort with cycle detection

Implementation notes:
- Uses Kahn's algorithm (BFS-based) with a min-heap to enforce lexicographic
  tie-breaking among nodes with equal in-degree at any point.
- Cycle detection: if the output doesn't include all nodes, a cycle exists.
  We then find nodes in the cycle via DFS coloring to report them.
- Dangling successor: validated upfront before sorting.
"""

import heapq
from collections import defaultdict


def topological_sort(graph: dict[str, list[str]]) -> list[str]:
    """Return a topological ordering of the directed graph.

    Raises ValueError if a cycle is detected or if a successor is not a key.
    """
    if not graph:
        return []

    # Validate: every successor must be a key in graph
    for node, successors in graph.items():
        for succ in successors:
            if succ not in graph:
                raise ValueError(
                    f"node '{succ}' is referenced as a successor but is not a key in the graph"
                )

    # Kahn's algorithm with lexicographic tie-breaking via min-heap
    in_degree: dict[str, int] = {node: 0 for node in graph}
    for node, successors in graph.items():
        for succ in successors:
            in_degree[succ] += 1

    # Initialize heap with all nodes that have in-degree 0
    heap: list[str] = [node for node, deg in in_degree.items() if deg == 0]
    heapq.heapify(heap)

    result: list[str] = []

    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for succ in sorted(graph[node]):  # sort for determinism (heap handles order)
            in_degree[succ] -= 1
            if in_degree[succ] == 0:
                heapq.heappush(heap, succ)

    if len(result) != len(graph):
        # There is a cycle — find nodes involved
        cycle_nodes = _find_cycle_nodes(graph)
        raise ValueError(f"cycle detected involving: {', '.join(sorted(cycle_nodes))}")

    return result


def _find_cycle_nodes(graph: dict[str, list[str]]) -> list[str]:
    """Return a list of nodes that are part of at least one cycle."""
    # 0 = unvisited, 1 = in current DFS stack, 2 = fully visited
    color = {node: 0 for node in graph}
    cycle_members: set[str] = set()

    def dfs(node: str, stack: list[str]) -> None:
        color[node] = 1
        stack.append(node)
        for succ in graph[node]:
            if color[succ] == 1:
                # Found a cycle — collect all nodes in the cycle
                cycle_start = succ
                in_cycle = False
                for n in stack:
                    if n == cycle_start:
                        in_cycle = True
                    if in_cycle:
                        cycle_members.add(n)
            elif color[succ] == 0:
                dfs(succ, stack)
        stack.pop()
        color[node] = 2

    for node in graph:
        if color[node] == 0:
            dfs(node, [])

    return list(cycle_members)
